package com.kovian.finance.ai.api; import com.kovian.finance.analytics.domain.*; import com.kovian.finance.transaction.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/v1/ai/finance") public class FinancialAiContextController {final FinancialTransactionRepository transactions; FinancialAiContextController(FinancialTransactionRepository t){transactions=t;} @GetMapping("/context") public Map<String,Object> context(@RequestParam UUID ownerId,@RequestParam LocalDate from,@RequestParam LocalDate to){var f=from.atStartOfDay().atOffset(ZoneOffset.UTC);var t=to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC);var tx=transactions.findByOwnerIdAndOccurredAtBetweenOrderByOccurredAtDesc(ownerId,f,t).stream().filter(x->x.getStatus()!=com.kovian.finance.transaction.domain.TransactionStatus.CANCELLED).map(x->Map.of("id",x.getId().toString(),"description",x.getDescription(),"amount",x.getAmount(),"type",x.getTransactionType().name(),"occurredAt",x.getOccurredAt().toString())).toList();return Map.of("ownerId",ownerId.toString(),"from",from.toString(),"to",to.toString(),"transactions",tx);}}